package hu.emlekor.naplo;
import android.app.Activity;
import android.app.AlertDialog;
import android.content.Intent;
import android.security.keystore.KeyGenParameterSpec;
import android.security.keystore.KeyProperties;
import android.text.InputType;
import android.util.AtomicFile;
import android.webkit.JavascriptInterface;
import android.widget.EditText;
import android.widget.LinearLayout;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.KeyStore;
import java.util.Arrays;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import org.json.JSONObject;

public final class MemoryBridge {
    interface Callback {void event(String kind,String value);}
    private final Activity activity;private final Callback callback;private final AtomicFile vault;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private String pendingExport;private volatile boolean busy;
    public MemoryBridge(Activity a,Callback c){activity=a;callback=c;vault=new AtomicFile(new File(a.getFilesDir(),"memories.enc"));}
    private SecretKey key(boolean existing)throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);String alias="emlekor.vault.v1";if(ks.containsAlias(alias))return (SecretKey)ks.getKey(alias,null);if(existing)throw new Exception("missing key");KeyGenerator gen=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder(alias,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());return gen.generateKey();}
    @JavascriptInterface public synchronized String load(){try{if(!vault.getBaseFile().exists()&&!new File(vault.getBaseFile()+".bak").exists())return "{\"ok\":true,\"data\":null}";byte[] data=vault.readFully();String raw=CryptoBox.open(key(true),new String(data,StandardCharsets.UTF_8),"emlekor.local.v1");return new JSONObject().put("ok",true).put("data",raw).toString();}catch(Exception e){return "{\"ok\":false,\"error\":\"A titkosított napló nem olvasható.\"}";}}
    @JavascriptInterface public synchronized String save(String raw){FileOutputStream stream=null;try{if(raw==null||raw.length()>8000000)throw new Exception();JSONObject obj=new JSONObject(raw);if(!"emlekor".equals(obj.optString("app"))||obj.optInt("version")!=1)throw new Exception();String enc=CryptoBox.seal(key(vault.getBaseFile().exists()),raw,"emlekor.local.v1");stream=vault.startWrite();stream.write(enc.getBytes(StandardCharsets.UTF_8));vault.finishWrite(stream);return "{\"ok\":true}";}catch(Exception e){if(stream!=null)vault.failWrite(stream);return "{\"ok\":false,\"error\":\"Nincs elég tárhely, vagy a titkosított tár nem írható.\"}";}}
    @JavascriptInterface public void exportBackup(final String raw){if(raw==null||raw.length()>8000000)return;activity.runOnUiThread(()->{if(busy)return;password(true,(pass)->{busy=true;worker.execute(()->{try{String enc=CryptoBox.exportBackup(raw,pass);Arrays.fill(pass,'\0');activity.runOnUiThread(()->{pendingExport=enc;Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"Emlekor-mentes.emlekor");try{activity.startActivityForResult(i,901);}catch(Exception e){busy=false;pendingExport=null;callback.event("error","A fájlválasztó nem nyitható meg.");}});}catch(Exception e){busy=false;callback.event("error","Nem sikerült titkosítani a másolatot.");}finally{Arrays.fill(pass,'\0');}});});});}
    @JavascriptInterface public void importBackup(){activity.runOnUiThread(()->{if(busy)return;busy=true;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");try{activity.startActivityForResult(i,902);}catch(Exception e){busy=false;callback.event("error","A fájlválasztó nem nyitható meg.");}});}
    @JavascriptInterface public void shareText(final String text){if(text==null||text.length()>20000)return;activity.runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,text);activity.startActivity(Intent.createChooser(i,"Emlék megosztása"));});}
    private interface PasswordAction {void accept(char[] password);}
    private void password(boolean creating,PasswordAction action){LinearLayout box=new LinearLayout(activity);box.setOrientation(LinearLayout.VERTICAL);int padding=(int)(24*activity.getResources().getDisplayMetrics().density);box.setPadding(padding,0,padding,0);EditText one=new EditText(activity);one.setHint(creating?"Legalább 8 karakter":"A mentés jelszava");one.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(one);EditText two=new EditText(activity);if(creating){two.setHint("Jelszó újra");two.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);box.addView(two);}AlertDialog dialog=new AlertDialog.Builder(activity).setTitle(creating?"Jelszavas másolat":"Mentés feloldása").setMessage(creating?"A jelszó a másik telefonon is kell. Nem állítható helyre.":"Add meg a mentés készítésekor megadott jelszót.").setView(box).setPositiveButton(creating?"Másolat készítése":"Feloldás",null).setNegativeButton("Mégse",(d,w)->{busy=false;callback.event("cancelled","A másolat kezelése megszakítva.");}).setOnCancelListener(d->{busy=false;callback.event("cancelled","A másolat kezelése megszakítva.");}).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String p=one.getText().toString();if(creating&&(p.length()<8||!p.equals(two.getText().toString()))){one.setError("Legalább 8 karakter, és mindkét jelszó egyezzen.");return;}if(!creating&&p.length()==0){one.setError("Add meg a jelszót.");return;}one.setText("");two.setText("");dialog.dismiss();action.accept(p.toCharArray());}));dialog.show();}
    public void result(int request,int result,Intent data){if(request!=901&&request!=902)return;if(result!=Activity.RESULT_OK||data==null||data.getData()==null){pendingExport=null;busy=false;callback.event("cancelled","A fájlművelet megszakítva.");return;}if(request==901){final String content=pendingExport;pendingExport=null;worker.execute(()->{try{if(content==null)throw new Exception();try(OutputStream out=activity.getContentResolver().openOutputStream(data.getData(),"wt")){if(out==null)throw new Exception();out.write(content.getBytes(StandardCharsets.UTF_8));}callback.event("exported","");}catch(Exception e){callback.event("error","A másolatfájl nem írható.");}finally{busy=false;}});}else worker.execute(()->{try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=activity.getContentResolver().openInputStream(data.getData())){if(in==null)throw new Exception();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>12000000)throw new Exception();out.write(b,0,n);}}String encrypted=new String(out.toByteArray(),StandardCharsets.UTF_8);activity.runOnUiThread(()->password(false,pass->worker.execute(()->{try{String raw=CryptoBox.importBackup(encrypted,pass);callback.event("restored",raw);}catch(Exception e){callback.event("error","Hibás jelszó vagy sérült másolat. A helyi emlékek megmaradtak.");}finally{Arrays.fill(pass,'\0');busy=false;}})));}catch(Exception e){busy=false;callback.event("error","A mentés nem olvasható vagy túl nagy.");}});}
    public void destroy(){worker.shutdown();}
}
